"""Make a source-linked experiment summary from real saved metrics, never hardcode scores."""
import json
from pathlib import Path

path = Path("reports/metrics.json")
metrics = json.loads(path.read_text(encoding="utf-8"))
test = metrics["test"]
dummy = metrics["test_dummy_baseline"]
lines = [
    "# Verified churn experiment results",
    "",
    "> Automatically generated by scripts/summarize_results.py from reports/metrics.json.",
    "> Values come from a real-data training run, not hypothetical examples.",
    "",
    f"- Dataset: {metrics['dataset']}",
    f"- Seed: {metrics['seed']}",
    f"- Total customers: **{metrics['rows_total']:,}**",
    f"- Training / validation / test: {metrics['rows_train']} / {metrics['rows_validation']} / {metrics['rows_test']}",
    f"- Full sample churn prevalence: {metrics['prevalence']:.1%}",
    f"- Selected model: **{metrics['selected_model']}**",
    f"- Tuned validation F2 threshold: **{test['threshold']:.2f}**",
    "",
    "## Final untouched test evaluation",
    "",
    "| Metric | Selected model | Dummy prior reference |",
    "| --- | ---: | ---: |",
]
for key, label in [
    ("average_precision", "Average precision"),
    ("roc_auc", "ROC-AUC"),
    ("precision", "Precision at threshold"),
    ("recall", "Recall at threshold"),
    ("f2", "F2 at threshold"),
    ("accuracy", "Accuracy"),
    ("brier_score", "Brier score (lower is better)"),
]:
    lines.append(f"| {label} | {test[key]:.4f} | {dummy[key]:.4f} |")
lines += [
    "",
    f"Test confusion matrix [[TN, FP], [FN, TP]]: `{test['confusion_matrix']}`.",
    "",
    "## Candidate comparison (training-only five-fold CV)",
    "",
    "| Model | Mean average precision | SD | Mean ROC-AUC |",
    "| --- | ---: | ---: | ---: |",
]
for row in metrics["cv_leaderboard"]:
    lines.append(
        f"| {row['model']} | {row['cv_average_precision_mean']:.4f} | "
        f"{row['cv_average_precision_std']:.4f} | {row['cv_roc_auc_mean']:.4f} |"
    )
lines += [
    "",
    "## Diagnostics",
    "",
    "![Target distribution](figures/target_distribution.png)",
    "",
    "![Precision-recall curve](figures/precision_recall.png)",
    "",
    "![ROC curve](figures/roc_curve.png)",
    "",
    "![Confusion matrix](figures/confusion_matrix.png)",
    "",
    "![Permutation feature importance](figures/permutation_importance.png)",
    "",
    "## Limitations",
    "",
    "Retrospective random holdout on one historical operator; no validation against",
    "future cohorts, demographic fairness, campaign uplift or production drift.",
    "The threshold was chosen to optimize validation F2, not retention ROI.",
    "Permutation importance is descriptive and cannot establish causality.",
]
Path("reports/EXPERIMENT.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("Wrote reports/EXPERIMENT.md from verified measurements")
